def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def norm_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return int(x[0]), int(x[1])
            except Exception:
                return None
        return None

    def get_pos(obs, keys):
        for k in keys:
            p = norm_pos(obs.get(k))
            if p is not None:
                return p
        return None

    def move_toward(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_target(src, items, prefer_max=False):
        if not items:
            return None
        good = []
        for it in items:
            p = norm_pos(it)
            if p is not None:
                good.append(p)
        if not good:
            return None
        if prefer_max:
            return max(good, key=lambda p: (manhattan(src, p), -p[0], -p[1]))
        return min(good, key=lambda p: (manhattan(src, p), p[0], p[1]))

    env = observation.get("environment_name", "resource_collection")
    self_pos = get_pos(observation, ("self_position", "position", "agent_position", "my_position"))
    opp_pos = get_pos(observation, ("opponent_position", "enemy_position", "target_position"))

    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = opp_pos
            if target is None:
                target = best_target(self_pos, observation.get("prey_positions") or observation.get("targets") or [])
            return move_toward(self_pos, target)
        corners = [(0, 0), (0, max(0, height - 1)), (max(0, width - 1), 0), (max(0, width - 1), max(0, height - 1))]
        if opp_pos is not None:
            target = max(corners, key=lambda c: (manhattan(c, opp_pos), c[0], c[1]))
        else:
            target = corners[0]
        return move_toward(self_pos, target)

    if env == "territory_control":
        candidates = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or observation.get("neutral_cells")
            or []
        )
        target = best_target(self_pos, candidates)
        if target is None:
            # Drift toward center or away from opponent if no explicit targets.
            if width and height:
                center = (width // 2, height // 2)
                if opp_pos is not None and self_pos is not None:
                    away = (self_pos[0] + clamp_step(self_pos[0] - opp_pos[0]), self_pos[1] + clamp_step(self_pos[1] - opp_pos[1]))
                    return move_toward(self_pos, away if manhattan(self_pos, away) > 0 else center)
                return move_toward(self_pos, center)
            return [0, 0]
        return move_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = best_target(self_pos, resources)
    if target is not None:
        return move_toward(self_pos, target)

    # If no resources, either pressure opponent or move to center.
    if opp_pos is not None:
        if width and height and self_pos is not None:
            center = (width // 2, height // 2)
            if manhattan(self_pos, opp_pos) <= 2:
                # avoid stalling too close when resources absent
                away = (self_pos[0] + clamp_step(self_pos[0] - opp_pos[0]), self_pos[1] + clamp_step(self_pos[1] - opp_pos[1]))
                return move_toward(self_pos, away if away != self_pos else center)
        return move_toward(self_pos, opp_pos)

    if width and height and self_pos is not None:
        return move_toward(self_pos, (width // 2, height // 2))

    return [0, 0]

